def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Extend each corner marker outward diagonally, preserving its own color.
    for r in range(h-1):
      for c in range(w-1):
        v=grid[r][c]
        if v and all(grid[rr][cc]==v for rr,cc in [(r,c+1),(r+1,c),(r+1,c+1)]):
          for sr,sc in [(r-1,c-1),(r-1,c+2),(r+2,c+2),(r+2,c-1)]:
            if 0<=sr<h and 0<=sc<w and grid[sr][sc]:
              color=grid[sr][sc]; dr=-1 if sr<r else 1; dc=-1 if sc<c else 1
              rr,cc=sr,sc
              while 0<=rr<h and 0<=cc<w:
                out[rr][cc]=color; rr+=dr; cc+=dc
          return out
    return out
